import heapq

def dodge_ships(n, m, ships):
    # Initialize the set of reachable points
    reachable = {(0, 0)}

    # Priority queue to store the next move
    pq = [(-0, 0, 0)]

    while pq:
        cost, x, y = heapq.heappop(pq)
        cost = -cost

        if cost == n:
            return ''.join(['-' if d == 0 else '+' if d > 0 else '0' for _, d in sorted(reachable)])

        for dx, dy in [(-1, 1), (0, 1), (1, 1)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in reachable:
                if any(x1 <= nx <= x2 and ny == y for x1, x2, _ in ships):
                    continue
                reachable.add((nx, ny))
                heapq.heappush(pq, (-cost - 1, nx, ny))

    return "impossible"

