    def dfs(x, y, dx, dy, visited):
        if x == n:
            return True
        if (x, y, dx, dy) in visited:
            return False
        visited.add((x, y, dx, dy))

        if 0 <= x + dx <= n and 0 <= y + dy <= n and all(not (x + dx, y + dy) in s for s in ships):
            if dfs(x + dx, y + dy, dx, dy, visited):
                return True

        if 0 <= x + dx - 1 <= n and 0 <= y + dy <= n and all(not (x + dx - 1, y + dy) in s for s in ships):
            if dfs(x + dx - 1, y + dy, dx - 1, dy, visited):
                return True

        if 0 <= x + dx + 1 <= n and 0 <= y + dy <= n and all(not (x + dx + 1, y + dy) in s for s in ships):
            if dfs(x + dx + 1, y + dy, dx + 1, dy, visited):
                return True

        visited.remove((x, y, dx, dy))
        return False

    ships = [set(range(x1, x2 + 1)) for x1, x2, y in ships]

    for dx in range(-1, 2):
        for dy in range(1, 2):
            if dfs(0, 0, dx, dy, set()):
                return "0" * abs(dx) + "+" * abs(dy)

    return "impossible"

